ALTER TABLE products ADD COLUMN hidden_seed INTEGER NOT NULL DEFAULT 0;
ALTER TABLE products ADD COLUMN preorder INTEGER NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN username TEXT;
CREATE UNIQUE INDEX users_username ON users(username) WHERE username IS NOT NULL;
CREATE TABLE runtime_flags(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE reservations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),variant_id TEXT NOT NULL REFERENCES variants(id),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 10),total INTEGER NOT NULL CHECK(total>=0),status TEXT NOT NULL DEFAULT 'PENDING_PAYMENT' CHECK(status IN ('PENDING_PAYMENT','PREORDER','FAILED','CANCELLED')),request_key TEXT NOT NULL,payment_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,request_key));
